package io.alvaroedo.skypost.core

import kotlinx.serialization.Serializable
import java.net.URLDecoder

/**
 * Boundary to the Rust core (`core/crates/keryx`, protocol v1).
 *
 * Phase 2 replaces [FakeKeryxCore] with bindings generated by UniFFI from a thin
 * `keryx-ffi` crate over `Keyring`, `message::encode/decode`, `uri` and
 * `backup`. All protocol logic (identities, codec, crypto, URIs, ARQ, lane
 * choice) stays in Rust; nothing here re-implements it.
 */
@Serializable
data class Card(
    /** Base32 X25519 public key. */
    val key: String,
    val alias: String,
    val callsign: String?,
    val isPharos: Boolean,
)

sealed interface ParsedUri {
    data class Id(val card: Card) : ParsedUri

    /** A group invitation. The URI itself is the secret. */
    data class Group(val name: String, val uri: String) : ParsedUri
}

interface KeryxCore {
    fun createIdentity(alias: String, callsign: String?): Card

    /** This station's `skypost:id/` URI (the QR payload). */
    fun identityUri(card: Card): String

    /** First fingerprint bytes as "4F2A 9C11 …", to compare by eye. */
    fun safetyNumber(key: String): String

    fun parseUri(text: String): ParsedUri?

    fun newGroupUri(name: String): String

    fun validAlias(alias: String): Boolean

    fun validCallsign(callsign: String): Boolean

    /** Phone number from user input: digits only, no `+`. */
    fun normalizePhone(input: String): String

    /** JS8 frames a text would take on air (stock phrases are cheaper). */
    fun framesFor(text: String, bridged: Boolean): Int

    /** JS8 frames a stock phrase (1-byte body) takes. */
    fun framesForPhrase(bridged: Boolean): Int

    /** Stock phrases in Spanish, id = index (`keryx::canned::PHRASES`). The app shows its own translations. */
    fun phrases(): List<String>
}

/**
 * Stand-in until the Rust core is linked. Its URI parsing and estimates are
 * rough approximations for the UI only; it produces no frames.
 */
class FakeKeryxCore : KeryxCore {
    private var seed = 0

    override fun createIdentity(alias: String, callsign: String?): Card =
        Card(key = fakeKey(alias), alias = alias, callsign = callsign, isPharos = false)

    override fun identityUri(card: Card): String = buildString {
        append("skypost:id/").append(card.key).append("?n=").append(card.alias)
        card.callsign?.let { append("&c=").append(it) }
        if (card.isPharos) append("&k=pharos")
    }

    override fun safetyNumber(key: String): String =
        key.take(20).uppercase().chunked(4).joinToString(" ")

    override fun parseUri(text: String): ParsedUri? {
        val t = text.trim()
        if (!t.startsWith("skypost:", ignoreCase = true)) return null
        val rest = t.substringAfter(':').trimStart('/')
        val path = rest.substringBefore('?')
        val params = rest.substringAfter('?', "").split('&')
            .mapNotNull { kv -> kv.split('=', limit = 2).takeIf { it.size == 2 }?.let { it[0] to URLDecoder.decode(it[1], "UTF-8") } }
            .toMap()
        val name = params["n"] ?: return null
        return when (path.substringBefore('/').lowercase()) {
            "id" -> ParsedUri.Id(
                Card(
                    key = path.substringAfter('/'),
                    alias = name,
                    callsign = params["c"],
                    isPharos = params["k"] == "pharos",
                ),
            )
            "group" -> ParsedUri.Group(name = name, uri = t)
            else -> null
        }
    }

    override fun newGroupUri(name: String): String = "skypost:group/${fakeKey(name)}?n=$name"

    override fun validAlias(alias: String): Boolean =
        alias.length in 1..16 && alias.all { it.isLetterOrDigit() || it in "_-." }

    override fun validCallsign(callsign: String): Boolean =
        callsign.length in 3..10 && callsign.all { it.isUpperCase() || it.isDigit() || it == '/' } &&
            callsign.any { it.isDigit() }

    override fun normalizePhone(input: String): String = input.filter { it.isDigit() }

    override fun framesFor(text: String, bridged: Boolean): Int {
        if (text.isBlank()) return 0
        val body = if (phrases().any { it.equals(text.trim(), ignoreCase = true) }) 1 else (text.length * 5 + 7) / 8
        val bytes = 4 + body + 8 + if (bridged) 2 else 0
        return (bytes + 8) / 9
    }

    override fun framesForPhrase(bridged: Boolean): Int = (4 + 1 + 8 + (if (bridged) 2 else 0) + 8) / 9

    override fun phrases(): List<String> = PHRASES

    private fun fakeKey(s: String): String {
        val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        var h = (s.hashCode() + 31 * seed++).toLong()
        return (1..52).joinToString("") {
            h = h * 6364136223846793005L + 1442695040888963407L
            alphabet[((h ushr 59).toInt() and 31)].toString()
        }
    }

    private companion object {
        /** `keryx::canned::PHRASES`, same order. */
        val PHRASES = listOf(
            "Estoy bien",
            "Todo bien, sin novedad",
            "Hemos llegado bien",
            "Necesito ayuda",
            "Vamos con retraso, no os preocupéis",
            "Mañana bajamos",
            "Volvemos hoy",
            "Hemos acampado",
            "Hace mal tiempo, esperamos",
            "Estamos a cubierto",
            "Cambio de planes",
            "Batería baja",
            "Mensaje recibido",
            "Sí",
            "No",
            "Te quiero",
            "Buenas noches",
            "Buenos días",
            "¿Estáis bien?",
            "Llamad a emergencias (112)",
        )
    }
}
